                      opacity: 0,
                      filter: "blur(12px)",
                      y: -120,
                      rotateX: 56,
                      scale: 2,
                    },
                    visible: {
                      opacity: 1,
                      filter: "blur(0px)",
                      y: 0,
                      scale: 1,
                      rotateX: 0,
