    <AudioLinesIcon className="size-6 -translate-x-0.5 mask-b-from-25% stroke-white text-white *:drop-shadow" />
    <AudioLinesIcon className="absolute inset-0 m-auto size-6 -translate-x-0.5 stroke-white text-white opacity-65 *:drop-shadow" />
  </div>
)

'use client'

import { LazyMotion, domAnimation, m, useAnimation } from 'motion/react'
import type { HTMLAttributes } from 'react'
import { forwardRef, useImperativeHandle, useRef, useEffect } from 'react'
import { cn } from '@/lib/utils'

export interface AudioLinesIconHandle {
    startAnimation: () => void
    stopAnimation: () => void
}

interface AudioLinesIconProps extends HTMLAttributes<HTMLDivElement> {
    size?: number
}

const AudioLinesIcon = forwardRef<AudioLinesIconHandle, AudioLinesIconProps>(({ className, size = 28, ...props }, ref) => {
    const controls = useAnimation()
    const isControlledRef = useRef(false)

    useImperativeHandle(ref, () => {
        isControlledRef.current = true

        return {
            startAnimation: () => controls.start('animate'),
            stopAnimation: () => controls.start('normal'),
        }
    })

    useEffect(() => {
        controls.start('animate')
    }, [controls])

    return (
        <LazyMotion features={domAnimation}>
        <div
            className={cn(className)}
            {...props}>
            <svg
                xmlns="http://www.w3.org/2000/svg"
                width={size}
                height={size}
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round">
                <path d="M2 10v3" />
                <m.path
                    variants={{
                        normal: { d: 'M6 6v11' },
                        animate: {
                            d: ['M6 6v11', 'M6 10v3', 'M6 6v11'],
                            transition: {
                                duration: 1.5,
                                repeat: Infinity,
                            },
                        },
                    }}
                    d="M6 6v11"
                    animate={controls}
                />
                <m.path
                    variants={{
                        normal: { d: 'M10 3v18' },
                        animate: {
                            d: ['M10 3v18', 'M10 9v5', 'M10 3v18'],
                            transition: {
                                duration: 1,
                                repeat: Infinity,
                            },
                        },
                    }}
                    d="M10 3v18"
                    animate={controls}
                />
                <m.path
                    variants={{
                        normal: { d: 'M14 8v7' },
                        animate: {
                            d: ['M14 8v7', 'M14 6v11', 'M14 8v7'],
                            transition: {
                                duration: 0.8,
                                repeat: Infinity,
                            },
                        },
                    }}
                    d="M14 8v7"
                    animate={controls}
                />
                <m.path
                    variants={{
                        normal: { d: 'M18 5v13' },
                        animate: {
                            d: ['M18 5v13', 'M18 7v9', 'M18 5v13'],
                            transition: {
                                duration: 1.5,
                                repeat: Infinity,
                            },
                        },
                    }}
                    d="M18 5v13"
                    animate={controls}
                />
                <path d="M22 10v3" />
            </svg>
        </div>

        </LazyMotion>)
})

AudioLinesIcon.displayName = 'AudioLinesIcon'

export { AudioLinesIcon }

